/**
 * Bangladesh's 64 districts for the travel map: SVG path data, Bangla and English names,
 * and a label point inside each district.
 *
 * Boundaries: geoBoundaries, built from BBS 2020 district boundaries (via OCHA HDX),
 * licensed CC BY 3.0 IGO. Projected (equirectangular, cos-latitude corrected) into a
 * 709×1000 viewBox and simplified to within ~0.8 map units. Regenerate from the source
 * rather than editing the paths by hand. Attribution is printed beside the map.
 */

export const DIVISIONS = ['Barishal', 'Chattogram', 'Dhaka', 'Khulna', 'Mymensingh', 'Rajshahi', 'Rangpur', 'Sylhet'] as const
export type Division = (typeof DIVISIONS)[number]

/** Bangla division names, for the map and the generated image. */
export const DIVISION_BN: Record<Division, string> = {
  Barishal: 'বরিশাল',
  Chattogram: 'চট্টগ্রাম',
  Dhaka: 'ঢাকা',
  Khulna: 'খুলনা',
  Mymensingh: 'ময়মনসিংহ',
  Rajshahi: 'রাজশাহী',
  Rangpur: 'রংপুর',
  Sylhet: 'সিলেট',
}

export interface District {
  id: string
  /** English name. */
  name: string
  /** Bangla name, drawn on the generated image. */
  nameBn: string
  division: Division
  /** Point inside the district where its label and pin are drawn. */
  label: readonly [number, number]
  /** Other spellings people search for, such as the source name. */
  aliases: readonly string[]
  /** Closed SVG path (one subpath per ring). */
  d: string
}

export const MAP_WIDTH = 709
export const MAP_HEIGHT = 1000

